@startuml

class User {
  + id : int
  + name : string
  + email : string
  + dateOfBirth : date
}

class Account {
  + accountNumber : int
}

class PersonalAccount {
}

class BusinessAccount {
  + companyName : string
  + monthlyFee : double
}

class Page {
  + pageName : string
  + visitCount : int
}

class AdvertisementPage {
  + bounceRate : float
  + clickThroughRate : float
  + conversionRate : float
}

class FriendRequest {
}

User "1" -- "1" Account
Account --|> PersonalAccount
Account --|> BusinessAccount
Account "1" *-- "*" Page
PersonalAccount "1" -- "*" PersonalAccount : friend
PersonalAccount "1" -- "*" FriendRequest
BusinessAccount "1" -- "*" AdvertisementPage
AdvertisementPage --|> Page
PersonalAccount "0..*" -- "*" Page : privilege

@enduml

